namespace ScreenshotTranslationUiTester;

// Shared AI-only UI words. No provider/model identifiers are translated.
internal static class AiUiText
{
    private static readonly Dictionary<string,string[]> Entries = new(StringComparer.Ordinal)
    {
        ["ExperimentalNoticeTitle"]=["AI 工具 · 实验版提示","AI 工具 · 實驗版提示","AI tools · Experimental feature","AI ツール・実験機能について","AI 도구 · 실험 기능 안내","Herramientas de IA · Función experimental","Outils IA · Fonction expérimentale","KI-Werkzeuge · Experimentelle Funktion","Инструменты ИИ · Экспериментальная функция"],
        ["ExperimentalNoticeBody"]=[
            "AI 工具仍处于实验阶段，尚未验证对所有游戏的兼容性与安全性。\n\nAI 生成的操作或代码可能修改游戏文件，导致游戏无法运行、文件损坏或存档丢失。请先备份游戏和存档，并尽量在副本上测试。",
            "AI 工具仍處於實驗階段，尚未驗證對所有遊戲的相容性與安全性。\n\nAI 產生的操作或程式碼可能修改遊戲檔案，導致遊戲無法執行、檔案損壞或存檔遺失。請先備份遊戲和存檔，並盡量在副本上測試。",
            "AI tools are experimental. Compatibility and safety have not been verified for every game.\n\nAI-generated actions or code may modify game files, stop a game from working, corrupt files, or cause save data loss. Back up your game and saves first, and test on a copy where possible.",
            "AI ツールは実験段階です。すべてのゲームで互換性と安全性が確認されているわけではありません。\n\nAI が生成した操作やコードによりゲームのファイルが変更され、起動不能、ファイル破損、セーブデータ消失が起こる可能性があります。先にゲームとセーブデータをバックアップし、可能ならコピーでテストしてください。",
            "AI 도구는 실험 단계이며 모든 게임에 대한 호환성과 안전성이 검증되지 않았습니다.\n\nAI가 생성한 작업이나 코드가 게임 파일을 수정하여 실행 오류, 파일 손상 또는 저장 데이터 손실을 일으킬 수 있습니다. 먼저 게임과 저장 데이터를 백업하고 가능하면 복사본에서 테스트하세요.",
            "Las herramientas de IA son experimentales. No se ha verificado su compatibilidad ni seguridad con todos los juegos.\n\nLas acciones o el código de la IA pueden modificar archivos, impedir que el juego funcione, dañarlos o causar la pérdida de partidas. Haz una copia de seguridad del juego y las partidas, y prueba en una copia cuando sea posible.",
            "Les outils IA sont expérimentaux. Leur compatibilité et leur sécurité ne sont pas vérifiées pour tous les jeux.\n\nLes actions ou le code générés peuvent modifier des fichiers, empêcher le jeu de fonctionner, endommager des fichiers ou entraîner la perte de sauvegardes. Sauvegardez le jeu et vos parties, puis testez sur une copie si possible.",
            "Die KI-Werkzeuge sind experimentell. Kompatibilität und Sicherheit wurden nicht für alle Spiele geprüft.\n\nKI-generierte Aktionen oder Programme können Spieldateien verändern, das Spiel unbenutzbar machen, Dateien beschädigen oder Spielstände löschen. Sichere zuerst das Spiel und deine Spielstände und teste möglichst mit einer Kopie.",
            "Инструменты ИИ находятся на экспериментальной стадии. Совместимость и безопасность проверены не для всех игр.\n\nДействия или код ИИ могут изменить файлы игры, нарушить её работу, повредить файлы или привести к потере сохранений. Сначала создайте резервные копии игры и сохранений и по возможности проверяйте работу на копии."],
        ["ExperimentalNoticeRemember"]=["不再提醒","不再提醒","Don't remind me again","今後表示しない","다시 알리지 않기","No volver a recordar","Ne plus me le rappeler","Nicht erneut erinnern","Больше не напоминать"],
        ["ExperimentalNoticeContinue"]=["继续使用","繼續使用","Continue","続ける","계속 사용","Continuar","Continuer","Weiter","Продолжить"],
        ["ExperimentalNoticeClose"]=["关闭","關閉","Close","閉じる","닫기","Cerrar","Fermer","Schließen","Закрыть"],
        ["ExperimentalNoticeSaveFailed"]=["未能保存“不再提醒”。请取消勾选后继续，或关闭窗口后检查数据目录的写入权限。","無法儲存「不再提醒」。請取消勾選後繼續，或關閉視窗並檢查資料目錄的寫入權限。","Could not save this preference. Uncheck it to continue, or close this window and check write access to the data folder.","設定を保存できませんでした。チェックを外して続けるか、この画面を閉じてデータフォルダーへの書き込み権限を確認してください。","설정을 저장하지 못했습니다. 선택을 해제하고 계속하거나 창을 닫고 데이터 폴더의 쓰기 권한을 확인하세요.","No se pudo guardar esta preferencia. Desmárcala para continuar o cierra la ventana y comprueba el acceso de escritura a la carpeta de datos.","Impossible d’enregistrer cette préférence. Décochez-la pour continuer ou fermez la fenêtre et vérifiez les droits d’écriture du dossier de données.","Die Einstellung konnte nicht gespeichert werden. Deaktiviere sie zum Fortfahren oder schließe das Fenster und prüfe die Schreibrechte für den Datenordner.","Не удалось сохранить настройку. Снимите флажок, чтобы продолжить, или закройте окно и проверьте права записи в папку данных."],
        ["CredentialRecoveryNotice"]=["部分 API 密钥无法在当前 Windows 账户读取。原有方案、连接和记录已保留；请在设置中重新填写翻译方案及 AI 连接的 API Key。","部分 API 金鑰無法在目前的 Windows 帳戶讀取。原有設定、連線與記錄已保留；請在設定中重新填寫翻譯方案與 AI 連線的 API Key。","Some API keys cannot be read by this Windows account. Existing plans, connections, and history are preserved. Re-enter the API keys for your translation plans and AI connections in Settings.","現在の Windows アカウントでは一部の API キーを読み取れません。設定、接続、履歴は保持されています。設定画面で翻訳と AI 接続の API キーを再入力してください。","현재 Windows 계정에서 일부 API 키를 읽을 수 없습니다. 기존 설정, 연결 및 기록은 보존되어 있습니다. 설정에서 번역 및 AI 연결의 API 키를 다시 입력하세요.","Esta cuenta de Windows no puede leer algunas claves API. Las configuraciones, conexiones y el historial se conservan. Vuelve a introducir las claves de traducción y conexiones de IA en Ajustes.","Ce compte Windows ne peut pas lire certaines clés API. Les configurations, connexions et historiques sont conservés. Saisissez à nouveau les clés de traduction et de connexion IA dans les paramètres.","Einige API-Schlüssel sind für dieses Windows-Konto nicht lesbar. Einstellungen, Verbindungen und Verlauf bleiben erhalten. Gib die Schlüssel für Übersetzung und KI-Verbindungen in den Einstellungen erneut ein.","Эта учётная запись Windows не может прочитать некоторые ключи API. Настройки, подключения и история сохранены. Заново введите ключи для перевода и подключений ИИ в настройках."],
