        ["ModelDefault"]=["模型默认","模型預設","Model default","モデルの既定値","모델 기본값","Predeterminado del modelo","Valeur par défaut du modèle","Modellstandard","По умолчанию модели"],
        ["ThinkingUnknown"]=["没有可确认的可调档位，使用模型默认设置。","沒有可確認的可調檔位，使用模型預設。","No verified adjustable levels. The model default is used.","調整可能な設定を確認できないため、モデルの既定値を使用します。","확인된 조절 단계가 없어 모델 기본값을 사용합니다.","No hay niveles ajustables verificados. Se usa el predeterminado.","Aucun niveau réglable vérifié. La valeur par défaut est utilisée.","Keine bestätigten einstellbaren Stufen. Der Modellstandard wird verwendet.","Подтверждённых уровней нет. Используется настройка модели по умолчанию."],
        ["Saved"]=["方案已保存，可回到 AI 工具选择使用。","方案已儲存，可回到 AI 工具選用。","Plan saved. Select it in AI tools to use it.","保存しました。AI ツールで選択して利用できます。","저장했습니다. AI 도구에서 선택해 사용하세요.","Plan guardado. Selecciónalo en Herramientas de IA.","Configuration enregistrée. Sélectionnez-la dans Outils IA.","Gespeichert. Wähle die Konfiguration unter KI-Werkzeuge.","Настройка сохранена. Выберите её в инструментах ИИ."],
        ["ModGameHint"]=["先选游戏，再查看该游戏的 MOD。","先選遊戲，再查看該遊戲的 MOD。","Choose a game to see its mods.","ゲームを選択して MOD を表示します。","게임을 선택하면 해당 MOD가 표시됩니다.","Elige un juego para ver sus mods.","Choisissez un jeu pour voir ses mods.","Wähle ein Spiel, um seine Mods zu sehen.","Выберите игру, чтобы увидеть её моды."],
        ["NoModGames"]=["还没有 MOD。可以在对话助手中讨论一个想法。","尚無 MOD。可先在對話助理中討論構想。","No mods yet. Start with an idea in the assistant.","MOD はまだありません。対話でアイデアを相談できます。","아직 MOD가 없습니다. 도우미에게 아이디어를 이야기하세요.","Aún no hay mods. Comenta una idea con el asistente.","Pas encore de mods. Discutez d’une idée avec l’assistant.","Noch keine Mods. Besprich eine Idee mit dem Assistenten.","Модов пока нет. Обсудите идею с помощником."],
        ["ModCount"]=["{0} 个 MOD","{0} 個 MOD","{0} mods","{0} 件の MOD","MOD {0}개","{0} mods","{0} mods","{0} Mods","Модов: {0}"],
        ["ViewAllGames"]=["所有游戏","所有遊戲","All games","すべてのゲーム","모든 게임","Todos los juegos","Tous les jeux","Alle Spiele","Все игры"],
        ["RunningOnlyHelp"]=["仅列出从 Fusion 启动且正在运行的游戏。","僅列出從 Fusion 啟動且執行中的遊戲。","Only games currently running from Fusion are listed.","Fusion から起動して実行中のゲームのみ表示します。","Fusion에서 실행 중인 게임만 표시됩니다.","Solo se muestran juegos en ejecución iniciados desde Fusion.","Seuls les jeux en cours lancés depuis Fusion sont affichés.","Nur über Fusion gestartete, laufende Spiele werden angezeigt.","Показаны только запущенные через Fusion игры."],
        ["ChooseSavedPlan"]=["选择已保存的方案，或到设置中添加一个。","選取已儲存的方案，或至設定新增。","Choose a saved plan, or add one in Settings.","保存済み設定を選ぶか、設定画面で追加してください。","저장한 설정을 선택하거나 설정 화면에서 추가하세요.","Elige un plan guardado o añade uno en Ajustes.","Choisissez une configuration ou ajoutez-en une dans Réglages.","Wähle eine gespeicherte Konfiguration oder erstelle eine in Einstellungen.","Выберите сохранённую настройку или добавьте её в настройках."],
        ["BillingHelp"]=["余额由服务方返回；未知费用不会显示为零。","餘額由服務商回傳；未知費用不顯示為零。","Balances come from the provider; unknown costs are never shown as zero.","残高は提供元の値です。不明な費用はゼロ表示しません。","잔액은 제공자가 반환하며 알 수 없는 비용은 0으로 표시하지 않습니다.","El proveedor informa del saldo; un coste desconocido no se muestra como cero.","Le solde vient du fournisseur ; un coût inconnu n’est jamais affiché à zéro.","Der Kontostand kommt vom Anbieter; unbekannte Kosten werden nicht als null angezeigt.","Баланс сообщает провайдер; неизвестные расходы не отображаются как нулевые."],
        ["AdvancedBilling"]=["余额查询的附加凭据（可选）","餘額查詢的附加憑證（選用）","Extra balance credentials (optional)","残高取得用の追加認証（任意）","잔액 조회 추가 인증(선택)","Credenciales adicionales de saldo (opcional)","Identifiants de solde supplémentaires (facultatif)","Zusätzliche Zugangsdaten für Kontostand (optional)","Дополнительные данные баланса (необязательно)"],
        ["PriceSettings"]=["费用估算单价（可选）","費用估算單價（選用）","Cost estimate prices (optional)","費用推定の単価（任意）","비용 예상 단가(선택)","Precios de estimación (opcional)","Tarifs d’estimation (facultatif)","Preise für Kostenschätzung (optional)","Тарифы для оценки расходов (необязательно)"],
        ["PriceHelp"]=["可填写每百万 token 的单价。填写后仅显示估算费用；留空表示未知，不影响发送。更换模型、地址或密钥后需重新确认单价。","可填寫每百萬 token 單價。填寫後僅顯示估算；留空為未知，不影響傳送。更換模型、位址或金鑰後需重新確認。","Optionally enter prices per million tokens. These produce estimates. Blank means unknown and does not block sending. Recheck prices after changing the model, address or key.","100 万トークンあたりの単価を任意入力できます。費用は推定値です。空欄でも送信できます。モデル・接続先・キーの変更後は再確認してください。","백만 토큰당 단가를 선택적으로 입력하세요. 비용은 예상치이며 비워도 전송할 수 있습니다. 모델, 주소 또는 키 변경 후 단가를 다시 확인하세요.","Introduce precios por millón de tokens si quieres estimaciones. Vacío significa desconocido y no impide enviar. Revisa los precios al cambiar modelo, dirección o clave.","Saisissez éventuellement les tarifs par million de tokens. Ce sont des estimations. Un champ vide signifie inconnu. Revérifiez après un changement de modèle, d’adresse ou de clé.","Optional Preise je Million Tokens eintragen. Die Kosten sind Schätzungen; leer bedeutet unbekannt und verhindert kein Senden. Nach Modell-, Adress- oder Schlüsselwechsel erneut prüfen.","Необязательно укажите цены за миллион токенов. Расходы будут оценочными. Пустое поле не мешает отправке. После смены модели, адреса или ключа проверьте цены заново."],
        ["PriceInput"]=["输入 / 百万 token","輸入 / 百萬 token","Input / million tokens","入力 / 100 万トークン","입력 / 백만 토큰","Entrada / millón de tokens","Entrée / million de tokens","Eingabe / Million Tokens","Вход / млн токенов"],
        ["PriceCache"]=["缓存输入 / 百万 token","快取輸入 / 百萬 token","Cached input / million tokens","キャッシュ入力 / 100 万トークン","캐시 입력 / 백만 토큰","Entrada en caché / millón","Entrée en cache / million","Cache-Eingabe / Million","Кэшированный вход / млн"],
        ["PriceOutput"]=["输出 / 百万 token","輸出 / 百萬 token","Output / million tokens","出力 / 100 万トークン","출력 / 백만 토큰","Salida / millón de tokens","Sortie / million de tokens","Ausgabe / Million Tokens","Выход / млн токенов"],
        ["PriceCurrency"]=["币种（例如 USD）","幣別（例如 USD）","Currency (for example USD)","通貨（例：USD）","통화(예: USD)","Moneda (por ejemplo USD)","Devise (par exemple USD)","Währung (z. B. USD)","Валюта (например USD)"],
        ["UserPrice"]=["用户设置","使用者設定","User settings","ユーザー設定","사용자 설정","Configuración del usuario","Réglages utilisateur","Benutzereinstellungen","Настройки пользователя"],
        ["PriceInvalid"]=["单价范围为 0 至 1,000,000；币种使用三位字母代码，例如 USD。","單價範圍為 0 至 1,000,000；幣別使用三位字母代碼，例如 USD。","Prices must be from 0 to 1,000,000. Use a three-letter currency code, such as USD.","単価は 0～1,000,000 で、通貨は USD など 3 文字のコードを使用してください。","단가는 0~1,000,000이며 통화는 USD와 같은 세 글자 코드를 사용하세요.","Los precios deben estar entre 0 y 1.000.000. Usa un código de moneda de tres letras, como USD.","Les tarifs doivent être compris entre 0 et 1 000 000. Utilisez un code devise de trois lettres, comme USD.","Preise müssen zwischen 0 und 1.000.000 liegen. Verwende einen dreistelligen Währungscode wie USD.","Цена должна быть от 0 до 1 000 000. Используйте трёхбуквенный код валюты, например USD."],
        ["RefreshFailed"]=["获取失败，请检查连接后重试。","取得失敗，請檢查連線後重試。","Could not retrieve data. Check the connection and retry.","取得できませんでした。接続を確認して再試行してください。","가져오지 못했습니다. 연결을 확인하고 다시 시도하세요.","No se pudieron obtener datos. Revisa la conexión y reintenta.","Impossible de récupérer les données. Vérifiez la connexion.","Abruf fehlgeschlagen. Verbindung prüfen und erneut versuchen.","Не удалось получить данные. Проверьте подключение."],
        ["ModelRequired"]=["请填写或选择模型 ID。","請填寫或選取模型 ID。","Enter or choose a model ID.","モデル ID を入力または選択してください。","모델 ID를 입력하거나 선택하세요.","Introduce o elige un ID de modelo.","Saisissez ou choisissez un ID de modèle.","Gib eine Modell-ID ein oder wähle sie aus.","Введите или выберите ID модели."],
        ["AgentOptionsError"]=["请检查助手类型、连接方式、服务商和程序位置。","請檢查助理類型、連線方式、服務商與程式位置。","Check the assistant type, connection method, provider and program location.","種類、接続方法、提供元、プログラムの場所を確認してください。","도우미 종류, 연결 방식, 제공자와 프로그램 위치를 확인하세요.","Revisa el tipo de asistente, conexión, proveedor y ubicación del programa.","Vérifiez le type d’assistant, la connexion, le fournisseur et le programme.","Prüfe Assistententyp, Verbindungsmethode, Anbieter und Programmpfad.","Проверьте тип помощника, подключение, провайдера и путь программы."],
        ["HarnessMissing"]=["找不到助手程序。请在设置中指定已安装的程序位置。","找不到助理程式。請至設定指定已安裝的程式位置。","Assistant program not found. Set its installed location in Settings.","アシスタントが見つかりません。設定でインストール先を指定してください。","도우미 프로그램을 찾을 수 없습니다. 설정에서 설치 위치를 지정하세요.","No se encuentra el asistente. Indica su ubicación instalada en Ajustes.","Programme introuvable. Indiquez son emplacement dans Réglages.","Assistentenprogramm nicht gefunden. Gib den Installationspfad in Einstellungen an.","Программа помощника не найдена. Укажите путь к ней в настройках."],
        ["HarnessStartError"]=["助手程序无法启动或版本不兼容。请检查程序位置与版本。","助理程式無法啟動或版本不相容。請檢查位置與版本。","The assistant could not start or its version is incompatible. Check its location and version.","起動できないか、非対応のバージョンです。場所とバージョンを確認してください。","도우미를 시작할 수 없거나 버전이 호환되지 않습니다. 위치와 버전을 확인하세요.","El asistente no inicia o su versión es incompatible. Revisa la ubicación y versión.","L’assistant ne démarre pas ou sa version est incompatible. Vérifiez le chemin et la version.","Der Assistent startet nicht oder die Version ist inkompatibel. Prüfe Pfad und Version.","Помощник не запускается или версия несовместима. Проверьте путь и версию."],
        ["HarnessResponseError"]=["助手没有完成本次请求。请检查账号或 API 连接后重试。","助理未完成本次請求。請檢查帳號或 API 連線後重試。","The assistant did not complete this request. Check its account or API connection and retry.","要求を完了できませんでした。アカウントまたは API 接続を確認してください。","요청을 완료하지 못했습니다. 계정 또는 API 연결을 확인한 후 다시 시도하세요.","El asistente no completó la solicitud. Comprueba la cuenta o la conexión API.","La requête n’a pas abouti. Vérifiez le compte ou la connexion API.","Der Assistent hat die Anfrage nicht abgeschlossen. Prüfe Konto oder API-Verbindung.","Помощник не выполнил запрос. Проверьте аккаунт или подключение API."],
        ["EffortUnavailable"]=["当前连接不能使用此思考档位，请改用“模型默认”。","目前連線無法使用此思考檔位，請改用「模型預設」。","This connection cannot use that thinking level. Select Model default.","この接続では指定の思考設定を使えません。モデルの既定値を選んでください。","이 연결에서는 해당 사고 수준을 사용할 수 없습니다. 모델 기본값을 선택하세요.","Esta conexión no admite ese nivel. Selecciona el predeterminado del modelo.","Cette connexion ne prend pas en charge ce niveau. Choisissez la valeur par défaut.","Diese Verbindung unterstützt diese Denktiefe nicht. Wähle den Modellstandard.","Это подключение не поддерживает выбранный уровень. Выберите настройку по умолчанию."],
        ["Connection"]=["AI 连接","AI 連線","AI connection","AI 接続","AI 연결","Conexión de IA","Connexion IA","KI-Verbindung","Подключение ИИ"],
        ["ChooseConnection"]=["选择连接和模型","選擇連線與模型","Choose a connection and model","接続とモデルを選択","연결 및 모델 선택","Elige una conexión y un modelo","Choisissez une connexion et un modèle","Verbindung und Modell wählen","Выберите подключение и модель"],
        ["ConnectionHelp"]=["在下方选择连接和模型，即可开始。无需启动游戏。","在下方選擇連線與模型，即可開始。無需啟動遊戲。","Choose a connection and model below to begin. No running game is required.","下で接続とモデルを選ぶと開始できます。ゲームの起動は不要です。","아래에서 연결과 모델을 선택하면 시작할 수 있습니다. 게임 실행은 필요하지 않습니다.","Elige abajo una conexión y un modelo para empezar. No necesitas ejecutar un juego.","Choisissez une connexion et un modèle ci-dessous. Aucun jeu en cours n’est nécessaire.","Wähle unten Verbindung und Modell. Ein laufendes Spiel ist nicht nötig.","Выберите подключение и модель внизу. Запускать игру не нужно."],
        ["DefaultConnectionModel"]=["默认模型（可选）","預設模型（選填）","Default model (optional)","既定のモデル（任意）","기본 모델(선택)","Modelo predeterminado (opcional)","Modèle par défaut (facultatif)","Standardmodell (optional)","Модель по умолчанию (необязательно)"],
        ["ConnectionModelHelp"]=["同一连接可使用多个模型。这里设置默认值，聊天时可选择其他模型。","同一連線可使用多個模型。此處設定預設值，聊天時可選擇其他模型。","One connection can use multiple models. Set a default here and choose another in chat.","1 つの接続で複数のモデルを使えます。ここでは既定値を設定し、対話中にも変更できます。","하나의 연결에서 여러 모델을 사용할 수 있습니다. 여기서 기본값을 정하고 대화에서 변경하세요.","Una conexión admite varios modelos. Define uno predeterminado aquí y cámbialo en el chat.","Une connexion peut utiliser plusieurs modèles. Définissez le modèle par défaut ici, puis changez-le dans le chat.","Eine Verbindung kann mehrere Modelle nutzen. Lege hier den Standard fest und wechsle im Chat.","Одно подключение поддерживает несколько моделей. Здесь задаётся вариант по умолчанию; в чате его можно изменить."],
        ["SessionOptionsHelp"]=["模型与思考程度仅用于当前对话。","模型與思考程度僅用於目前對話。","Model and thinking level apply to this conversation.","モデルと思考設定はこの対話に適用されます。","모델과 사고 수준은 현재 대화에 적용됩니다.","El modelo y el razonamiento se aplican a esta conversación.","Le modèle et le niveau de réflexion s’appliquent à cette conversation.","Modell und Denktiefe gelten für dieses Gespräch.","Модель и уровень рассуждения относятся к этому диалогу."],
        ["GeneralChat"]=["编程与对话","程式開發與對話","Coding and chat","開発と対話","개발 및 대화","Programación y chat","Code et conversation","Programmieren und Chat","Код и диалог"],
        ["GameOptional"]=["关联游戏（可选）","關聯遊戲（選填）","Link game (optional)","ゲームを関連付け（任意）","게임 연결(선택)","Vincular juego (opcional)","Associer un jeu (facultatif)","Spiel verknüpfen (optional)","Связать игру (необязательно)"],
        ["UnlinkGame"]=["取消游戏关联","取消遊戲關聯","Unlink game","ゲームの関連付けを解除","게임 연결 해제","Desvincular juego","Dissocier le jeu","Spielverknüpfung lösen","Отвязать игру"],
        ["GameForTools"]=["操作游戏前，请关联正在运行的游戏。","操作遊戲前，請關聯執行中的遊戲。","Link a running game before using game tools.","ゲームツールを使うには起動中のゲームを関連付けてください。","게임 도구를 사용하기 전에 실행 중인 게임을 연결하세요.","Vincula un juego en ejecución antes de usar sus herramientas.","Associez un jeu en cours avant d’utiliser les outils de jeu.","Verknüpfe für Spielwerkzeuge ein laufendes Spiel.","Для игровых инструментов сначала свяжите запущенную игру."],
        ["NativeWelcomeTitle"]=["想做些什么？","想做些什麼？","What would you like to do?","何をしましょうか？","무엇을 도와드릴까요?","¿Qué quieres hacer?","Que souhaitez-vous faire ?","Was möchtest du machen?","Что вы хотите сделать?"],
        ["NativeWelcomeBody"]=["直接描述目标。可以编程、分析文件或制作 MOD；需要操作游戏时再关联游戏。","直接描述目標。可以開發程式、分析檔案或製作 MOD；需要操作遊戲時再關聯遊戲。","Describe your goal: write code, analyze files or build a mod. Link a game when you need game tools.","コード作成、ファイル分析、MOD 制作など、目標を入力してください。ゲーム操作が必要なときにゲームを関連付けます。","코드 작성, 파일 분석, MOD 제작 등 목표를 설명하세요. 게임 도구가 필요할 때 게임을 연결하면 됩니다.","Describe tu objetivo: programar, analizar archivos o crear un mod. Vincula un juego cuando necesites sus herramientas.","Décrivez votre objectif : coder, analyser des fichiers ou créer un mod. Associez un jeu lorsque ses outils sont nécessaires.","Beschreibe dein Ziel: Code schreiben, Dateien analysieren oder einen Mod erstellen. Verknüpfe bei Bedarf ein Spiel.","Опишите цель: написать код, изучить файлы или создать мод. Свяжите игру, когда понадобятся игровые инструменты."],
        ["ComposerHint"]=["描述目标，或提出问题…","描述目標，或提出問題…","Describe a goal or ask a question…","目標や質問を入力…","목표를 설명하거나 질문하세요…","Describe un objetivo o haz una pregunta…","Décrivez un objectif ou posez une question…","Beschreibe ein Ziel oder stelle eine Frage…","Опишите цель или задайте вопрос…"],
        ["ChooseWorkspace"]=["选择项目文件夹","選擇專案資料夾","Choose project folder","プロジェクトフォルダーを選択","프로젝트 폴더 선택","Elegir carpeta del proyecto","Choisir le dossier du projet","Projektordner wählen","Выбрать папку проекта"],
        ["Workspace"]=["项目文件夹","專案資料夾","Project folder","プロジェクトフォルダー","프로젝트 폴더","Carpeta del proyecto","Dossier du projet","Projektordner","Папка проекта"],
        ["WorkspaceDefault"]=["未选择时，为此对话使用独立项目文件夹。","未選擇時，為此對話使用獨立專案資料夾。","Without a selection, this conversation uses its own project folder.","未選択の場合、この対話専用のフォルダーを使います。","선택하지 않으면 이 대화 전용 프로젝트 폴더를 사용합니다.","Si no eliges una carpeta, la conversación usa su propia carpeta de proyecto.","Sans sélection, cette conversation utilise son propre dossier de projet.","Ohne Auswahl nutzt dieses Gespräch einen eigenen Projektordner.","Если папка не выбрана, для диалога используется отдельная папка проекта."],
        ["Permissions"]=["操作权限","操作權限","Permissions","操作権限","작업 권한","Permisos","Autorisations","Berechtigungen","Разрешения"],
        ["PermissionAsk"]=["请求批准","請求批准","Ask for approval","承認を求める","승인 요청","Solicitar aprobación","Demander une autorisation","Genehmigung anfragen","Запрашивать разрешение"],
        ["PermissionAuto"]=["帮我批准","幫我批准","Review for me","承認を自動審査","자동 승인 검토","Revisar por mí","Examiner pour moi","Für mich prüfen","Проверять за меня"],
        ["PermissionFull"]=["完全访问","完整存取","Full access","フルアクセス","전체 접근","Acceso completo","Accès complet","Vollzugriff","Полный доступ"],
        ["PermissionAskHelp"]=["超出权限边界的操作会请求你批准。","超出權限範圍的操作會請求你批准。","Operations beyond the permission boundary ask for your approval.","権限範囲を超える操作は承認を求めます。","권한 범위를 벗어나는 작업은 승인을 요청합니다.","Las operaciones fuera de los permisos solicitan tu aprobación.","Les opérations hors du périmètre autorisé demandent votre accord.","Aktionen außerhalb der Berechtigung fragen nach deiner Zustimmung.","Действия за пределами разрешений запрашивают ваше согласие."],
        ["PermissionAutoHelp"]=["由 Codex 审查操作，需要你决定时再询问。","由 Codex 審查操作，需要你決定時再詢問。","Codex reviews operations and asks when your decision is needed.","Codex が操作を審査し、判断が必要な場合に確認します。","Codex가 작업을 검토하고 사용자 판단이 필요할 때 묻습니다.","Codex revisa las operaciones y pregunta cuando necesita tu decisión.","Codex examine les opérations et demande votre décision si nécessaire.","Codex prüft Aktionen und fragt, wenn deine Entscheidung nötig ist.","Codex проверяет действия и обращается к вам при необходимости."],
        ["PermissionAutoUnsupported"]=["OpenCode 暂不支持风险自动审查，请选择其他权限。","OpenCode 尚不支援風險自動審查，請選擇其他權限。","OpenCode does not support automatic risk review. Choose another permission mode.","OpenCode はリスクの自動審査に対応していません。別の権限を選んでください。","OpenCode는 자동 위험 검토를 지원하지 않습니다. 다른 권한 모드를 선택하세요.","OpenCode no admite revisión automática de riesgos. Elige otro modo.","OpenCode ne prend pas en charge l’examen automatique des risques. Choisissez un autre mode.","OpenCode unterstützt keine automatische Risikoprüfung. Wähle einen anderen Modus.","OpenCode не поддерживает автоматическую оценку риска. Выберите другой режим."],
        ["PermissionFullHelp"]=["允许助手访问项目外文件和网络，并执行命令。操作可能直接修改文件；仅在你愿意授予此范围时开启。","允許助理存取專案外檔案與網路，並執行命令。操作可能直接修改檔案；僅在願意授予此範圍時開啟。","Allow access to files outside the project and the network, and command execution. Actions may directly change files. Enable only if you want to grant this scope.","プロジェクト外のファイル、ネットワーク、コマンド実行を許可します。ファイルが直接変更される場合があります。この範囲を許可する場合に有効にしてください。","프로젝트 외부 파일과 네트워크 접근, 명령 실행을 허용합니다. 파일이 직접 변경될 수 있습니다. 이 범위를 허용하려는 경우에만 켜세요.","Permite acceder a archivos externos al proyecto y a la red, y ejecutar comandos. Puede modificar archivos directamente. Actívalo solo si deseas conceder ese alcance.","Autorise les fichiers hors du projet, le réseau et l’exécution de commandes. Les fichiers peuvent être modifiés directement. Activez uniquement si vous souhaitez accorder cet accès.","Erlaubt Zugriff auf Dateien außerhalb des Projekts, Netzwerk und Befehlsausführung. Dateien können direkt geändert werden. Aktiviere dies nur, wenn du diesen Umfang erlauben möchtest.","Разрешает доступ к файлам вне проекта, сети и запуск команд. Файлы могут изменяться напрямую. Включайте, только если хотите предоставить такие права."],
        ["AgentMode"]=["工作方式","工作方式","Work mode","作業モード","작업 모드","Modo de trabajo","Mode de travail","Arbeitsmodus","Режим работы"],
        ["AgentBuild"]=["执行任务","執行工作","Build","実行","실행","Ejecutar","Exécuter","Ausführen","Выполнение"],
        ["AgentPlan"]=["制定计划","制定計畫","Plan","計画","계획","Planificar","Planifier","Planen","Планирование"],
        ["NativeApproval"]=["等待批准","等待批准","Approval needed","承認待ち","승인 필요","Aprobación necesaria","Autorisation nécessaire","Genehmigung erforderlich","Требуется разрешение"],
        ["NativeQuestion"]=["需要你的回答","需要你的回答","Your answer is needed","回答が必要です","답변이 필요합니다","Se necesita tu respuesta","Votre réponse est nécessaire","Deine Antwort wird benötigt","Нужен ваш ответ"],
        ["SubmitAnswer"]=["提交回答","提交回答","Submit answer","回答を送信","답변 제출","Enviar respuesta","Envoyer la réponse","Antwort senden","Отправить ответ"],
        ["AnswerRequired"]=["请回答每个问题后再提交。","請回答每個問題後再提交。","Answer each question before submitting.","すべての質問に回答してください。","모든 질문에 답한 후 제출하세요.","Responde a cada pregunta antes de enviar.","Répondez à chaque question avant d’envoyer.","Beantworte vor dem Senden jede Frage.","Ответьте на все вопросы перед отправкой."],
        ["AllowOnce"]=["允许这一次","允許這一次","Allow once","今回のみ許可","이번만 허용","Permitir una vez","Autoriser cette fois","Einmal erlauben","Разрешить один раз"],
        ["AllowSession"]=["本会话允许","此對話允許","Allow for this session","このセッションで許可","이 세션에서 허용","Permitir en esta sesión","Autoriser pour cette session","Für diese Sitzung erlauben","Разрешить в этом сеансе"],
        ["Deny"]=["拒绝","拒絕","Deny","拒否","거부","Denegar","Refuser","Ablehnen","Отклонить"],
        ["CancelTurn"]=["取消本轮","取消本輪","Cancel turn","今回の処理を中止","이번 작업 취소","Cancelar turno","Annuler cet échange","Runde abbrechen","Отменить этот ход"],
        ["AllowCommandRule"]=["允许匹配的命令","允許相符的命令","Allow matching commands","一致するコマンドを許可","일치하는 명령 허용","Permitir comandos coincidentes","Autoriser les commandes correspondantes","Passende Befehle erlauben","Разрешить соответствующие команды"],
        ["AllowNetworkRule"]=["允许此网络规则","允許此網路規則","Allow network rule","このネットワーク規則を許可","이 네트워크 규칙 허용","Permitir regla de red","Autoriser cette règle réseau","Netzwerkregel erlauben","Разрешить правило сети"],
        ["SetupWindowsSandbox"]=["设置 Windows 沙箱","設定 Windows 沙箱","Set up Windows sandbox","Windows サンドボックスを設定","Windows 샌드박스 설정","Configurar entorno aislado de Windows","Configurer le bac à sable Windows","Windows-Sandbox einrichten","Настроить песочницу Windows"],
        ["SetupCodexWindowsSandbox"]=["设置 Codex Windows 沙箱","設定 Codex Windows 沙箱","Set up Codex Windows sandbox","Codex Windows サンドボックスを設定","Codex Windows 샌드박스 설정","Configurar entorno aislado de Codex en Windows","Configurer le bac à sable Windows de Codex","Codex-Windows-Sandbox einrichten","Настроить песочницу Codex в Windows"],
        ["NativeReasoning"]=["正在思考…","正在思考…","Thinking…","考えています…","생각 중…","Razonando…","Réflexion…","Denkt nach…","Обдумывание…"],
        ["NativeTool"]=["正在执行工具…","正在執行工具…","Running a tool…","ツールを実行中…","도구 실행 중…","Ejecutando herramienta…","Exécution d’un outil…","Werkzeug wird ausgeführt…","Выполнение инструмента…"],
        ["NativeWorking"]=["正在处理…","正在處理…","Working…","処理中…","처리 중…","Procesando…","Traitement…","In Bearbeitung…","Выполнение…"],
        ["NoModelsFound"]=["未返回可用模型，可手动输入模型 ID。","未傳回可用模型，可手動輸入模型 ID。","No models returned. You can enter a model ID manually.","モデルが返されませんでした。モデル ID を手動入力できます。","모델이 반환되지 않았습니다. 모델 ID를 직접 입력할 수 있습니다.","No se devolvieron modelos. Puedes escribir un ID manualmente.","Aucun modèle reçu. Vous pouvez saisir un identifiant manuellement.","Keine Modelle erhalten. Du kannst eine Modell-ID eingeben.","Модели не получены. Можно ввести ID вручную."],
        ["NativeCapabilityHelp"]=["助手在所选项目文件夹中工作，按当前权限读取、编辑文件和执行命令。关联游戏后可使用 Fusion 游戏工具。","助理在所選專案資料夾中工作，依目前權限讀取、編輯檔案與執行命令。關聯遊戲後可使用 Fusion 遊戲工具。","The assistant works in the selected project folder, reading and editing files and running commands within its permissions. Link a game to use Fusion game tools.","選択したフォルダー内で、権限に応じてファイルの読み書きやコマンド実行を行います。ゲームを関連付けると Fusion のゲームツールを利用できます。","선택한 프로젝트 폴더에서 권한에 따라 파일을 읽고 편집하며 명령을 실행합니다. 게임을 연결하면 Fusion 게임 도구를 사용할 수 있습니다.","El asistente trabaja en la carpeta seleccionada: lee, edita y ejecuta comandos según sus permisos. Vincula un juego para usar las herramientas de Fusion.","L’assistant travaille dans le dossier sélectionné : lecture, modification et commandes selon ses autorisations. Associez un jeu pour utiliser les outils Fusion.","Der Assistent liest und bearbeitet Dateien und führt Befehle im gewählten Projekt entsprechend den Berechtigungen aus. Verknüpfe ein Spiel für Fusion-Spielwerkzeuge.","Помощник работает в выбранной папке: читает и редактирует файлы, запускает команды согласно разрешениям. Свяжите игру для инструментов Fusion."],
        ["NativeBudgetHelp"]=["支持随时手动停止。","支援隨時手動停止。","You can stop at any time.","いつでも停止できます。","언제든지 중지할 수 있습니다.","Puedes detenerlo en cualquier momento.","Vous pouvez arrêter à tout moment.","Sie können jederzeit stoppen.","Можно остановить в любой момент."],
        ["ApiBalance145"]=["API 余额","API 餘額","API balance","API 残高","API 잔액","Saldo API","Solde API","API-Guthaben","Баланс API"],
        ["PermissionModeError"]=["此助手无法使用所选权限，请重新选择。","此助理無法使用所選權限，請重新選擇。","This assistant cannot use the selected permission mode. Choose another.","このアシスタントでは選択した権限を使えません。選び直してください。","이 도우미는 선택한 권한을 사용할 수 없습니다. 다시 선택하세요.","Este asistente no admite el permiso seleccionado. Elige otro.","Cet assistant ne peut pas utiliser ce mode. Choisissez-en un autre.","Dieser Assistent unterstützt den gewählten Berechtigungsmodus nicht.","Помощник не поддерживает выбранный режим разрешений."],
        ["WindowsSandboxError"]=["Windows 沙箱尚未配置成功，请检查 Codex 沙箱设置后重试。","Windows 沙箱尚未設定成功，請檢查 Codex 沙箱設定後重試。","Windows sandbox setup is incomplete. Check Codex sandbox settings and retry.","Windows サンドボックスの設定が未完了です。Codex の設定を確認して再試行してください。","Windows 샌드박스 설정이 완료되지 않았습니다. Codex 설정을 확인하고 다시 시도하세요.","La configuración del entorno aislado de Windows está incompleta. Revisa Codex y reintenta.","La configuration du bac à sable Windows est incomplète. Vérifiez Codex puis réessayez.","Die Windows-Sandbox ist nicht fertig eingerichtet. Prüfe die Codex-Einstellungen.","Настройка песочницы Windows не завершена. Проверьте параметры Codex и повторите попытку."],
        ["NativeSessionError"]=["无法恢复此助手会话，请新建对话重试。历史记录已保留。","無法恢復此助理對話，請新增對話重試。歷史記錄已保留。","This assistant session cannot be resumed. Start a new conversation. History is preserved.","このセッションを再開できません。新しい対話を開始してください。履歴は保持されています。","이 세션을 재개할 수 없습니다. 새 대화를 시작하세요. 기록은 보존됩니다.","No se puede reanudar esta sesión. Inicia otra conversación. El historial se conserva.","Impossible de reprendre cette session. Ouvrez une nouvelle conversation. L’historique est conservé.","Diese Sitzung kann nicht fortgesetzt werden. Starte ein neues Gespräch; der Verlauf bleibt erhalten.","Не удалось продолжить сеанс. Начните новый диалог. История сохранена."],
        ["NativeWorkspaceError"]=["无法使用此项目文件夹，请选择有效的本地文件夹。","無法使用此專案資料夾，請選擇有效的本機資料夾。","This project folder is unavailable. Select a valid local folder.","このフォルダーは利用できません。有効なローカルフォルダーを選んでください。","이 프로젝트 폴더를 사용할 수 없습니다. 유효한 로컬 폴더를 선택하세요.","La carpeta no está disponible. Elige una carpeta local válida.","Ce dossier est indisponible. Choisissez un dossier local valide.","Dieser Projektordner ist nicht verfügbar. Wähle einen gültigen lokalen Ordner.","Папка проекта недоступна. Выберите допустимую локальную папку."],
        ["NativePromptEmpty"]=["请输入消息后再发送。","請輸入訊息後再傳送。","Enter a message before sending.","メッセージを入力してください。","메시지를 입력하세요.","Escribe un mensaje antes de enviarlo.","Saisissez un message avant d’envoyer.","Gib eine Nachricht ein.","Введите сообщение перед отправкой."],
        ["NativeAgentError"]=["此助手不支持所选工作方式。","此助理不支援所選工作方式。","This assistant does not support the selected work mode.","この作業モードは対応していません。","선택한 작업 모드를 지원하지 않습니다.","El asistente no admite ese modo de trabajo.","L’assistant ne prend pas en charge ce mode.","Dieser Arbeitsmodus wird nicht unterstützt.","Этот режим работы не поддерживается."],
        ["NativeUncertain"]=["无法确认请求是否已执行，已停止自动重试。请先检查会话和文件结果。","無法確認請求是否已執行，已停止自動重試。請先檢查對話與檔案結果。","Execution could not be confirmed. Automatic retries stopped. Check the session and files before retrying.","実行結果を確認できないため自動再試行を停止しました。対話とファイルを確認してください。","실행 여부를 확인할 수 없어 자동 재시도를 중지했습니다. 세션과 파일을 먼저 확인하세요.","No se pudo confirmar la ejecución. Se detuvieron los reintentos automáticos. Revisa la sesión y los archivos.","L’exécution n’a pas pu être confirmée. Les relances automatiques sont arrêtées. Vérifiez la session et les fichiers.","Die Ausführung ist unklar; automatische Wiederholungen wurden gestoppt. Prüfe zuerst Sitzung und Dateien.","Выполнение не подтверждено. Автоповторы остановлены. Сначала проверьте сеанс и файлы."],
        ["NativeNotAdmitted"]=["助手未接受本轮请求，请检查连接后重试。","助理未接受本輪請求，請檢查連線後重試。","The assistant did not accept this request. Check the connection and retry.","要求が受理されませんでした。接続を確認して再試行してください。","요청이 수락되지 않았습니다. 연결을 확인하고 다시 시도하세요.","El asistente no aceptó la solicitud. Revisa la conexión y reintenta.","La demande n’a pas été acceptée. Vérifiez la connexion et réessayez.","Die Anfrage wurde nicht angenommen. Prüfe die Verbindung und versuche es erneut.","Запрос не принят. Проверьте подключение и повторите попытку."],
        ["NativeEventError"]=["助手进度连接中断，请检查会话状态。","助理進度連線中斷，請檢查對話狀態。","The assistant’s progress connection was interrupted. Check the session status.","進捗の接続が切断されました。セッション状態を確認してください。","진행 상황 연결이 끊겼습니다. 세션 상태를 확인하세요.","Se interrumpió la conexión de progreso. Revisa el estado de la sesión.","La connexion de suivi a été interrompue. Vérifiez la session.","Die Fortschrittsverbindung wurde unterbrochen. Prüfe den Sitzungsstatus.","Соединение для отслеживания прервано. Проверьте состояние сеанса."],
        ["NativeReconnecting"]=["正在重新连接助手…","正在重新連線助理…","Reconnecting to the assistant…","アシスタントに再接続中…","도우미에 다시 연결 중…","Reconectando con el asistente…","Reconnexion à l’assistant…","Verbindung zum Assistenten wird wiederhergestellt…","Переподключение к помощнику…"],
        ["NativeApprovalUnavailable"]=["批准请求已失效或无法提交，请检查当前会话。","批准請求已失效或無法提交，請檢查目前對話。","This approval expired or could not be submitted. Check the current session.","承認が期限切れか送信できません。現在のセッションを確認してください。","승인 요청이 만료되었거나 제출할 수 없습니다. 현재 세션을 확인하세요.","La aprobación caducó o no se pudo enviar. Revisa la sesión actual.","L’autorisation a expiré ou n’a pas pu être envoyée. Vérifiez la session.","Die Genehmigung ist abgelaufen oder konnte nicht gesendet werden. Prüfe die Sitzung.","Запрос разрешения истёк или не отправлен. Проверьте текущий сеанс."],
        ["NativeQuestionUnavailable"]=["问题已失效或回答无法提交，请检查当前会话。","問題已失效或回答無法提交，請檢查目前對話。","This question expired or the answer could not be submitted. Check the current session.","質問が期限切れか回答を送信できません。セッションを確認してください。","질문이 만료되었거나 답변을 제출할 수 없습니다. 세션을 확인하세요.","La pregunta caducó o no se pudo enviar la respuesta. Revisa la sesión.","La question a expiré ou la réponse n’a pas pu être envoyée. Vérifiez la session.","Die Frage ist abgelaufen oder die Antwort konnte nicht gesendet werden. Prüfe die Sitzung.","Вопрос устарел или ответ не отправлен. Проверьте сеанс."],
        ["native_windows_setup_title"]=["设置 Codex Windows 沙箱","設定 Codex Windows 沙箱","Set up Codex Windows sandbox","Codex Windows サンドボックスの設定","Codex Windows 샌드박스 설정","Configurar entorno aislado de Codex en Windows","Configurer le bac à sable Windows de Codex","Codex-Windows-Sandbox einrichten","Настроить песочницу Codex в Windows"],
        ["native_windows_setup_detail"]=["Codex 需要先配置 Windows 沙箱。继续将调用 Codex 的原生设置流程，可能请求系统权限。你也可以取消本轮。","Codex 需要先設定 Windows 沙箱。繼續將呼叫 Codex 原生設定流程，可能請求系統權限。也可取消本輪。","Codex needs its Windows sandbox configured. Continuing starts Codex’s native setup, which may request system permissions. You can cancel this turn.","Windows サンドボックスの設定が必要です。続行すると Codex の設定処理が始まり、システム権限を求める場合があります。今回は中止できます。","Codex의 Windows 샌드박스 설정이 필요합니다. 계속하면 기본 설정 절차가 실행되며 시스템 권한을 요청할 수 있습니다. 이번 작업을 취소할 수 있습니다.","Codex necesita configurar su entorno aislado de Windows. Continuar inicia su configuración nativa, que puede solicitar permisos del sistema. Puedes cancelar este turno.","Codex doit configurer son bac à sable Windows. Continuer lance sa configuration native, qui peut demander des droits système. Vous pouvez annuler cet échange.","Codex muss seine Windows-Sandbox einrichten. Fortfahren startet die native Einrichtung, die Systemrechte anfordern kann. Du kannst diese Runde abbrechen.","Codex требуется настроить песочницу Windows. Продолжение запускает встроенную настройку, которая может запросить системные права. Можно отменить этот ход."],
        ["native_windows_setup_progress"]=["正在设置 Windows 沙箱…","正在設定 Windows 沙箱…","Setting up Windows sandbox…","Windows サンドボックスを設定中…","Windows 샌드박스 설정 중…","Configurando entorno aislado de Windows…","Configuration du bac à sable Windows…","Windows-Sandbox wird eingerichtet…","Настройка песочницы Windows…"],
        ["Stopped"]=["已停止","已停止","Stopped","停止しました","중지됨","Detenido","Arrêté","Gestoppt","Остановлено"],
        ["harness_permission_rejected"]=["操作已拒绝，本轮已停止。你可以继续对话。","操作已拒絕，此輪已停止。可以繼續對話。","The operation was denied and this turn stopped. You can continue the conversation.","操作を拒否し、今回の処理を停止しました。対話は続けられます。","작업이 거부되어 이번 처리가 중지되었습니다. 대화를 계속할 수 있습니다.","Se rechazó la operación y se detuvo el turno. Puedes continuar la conversación.","L’opération a été refusée et cet échange arrêté. Vous pouvez continuer la conversation.","Die Aktion wurde abgelehnt und die Runde gestoppt. Du kannst das Gespräch fortsetzen.","Действие отклонено, этот ход остановлен. Можно продолжить диалог."],
        ["harness_provider_stream_error"]=["服务商响应流返回错误，本轮已停止，未采用不完整结果。","服務商回應串流傳回錯誤，此輪已停止，未採用不完整結果。","The provider response stream returned an error. This turn stopped without using incomplete results.","提供元の応答ストリームでエラーが発生しました。不完全な結果を使わずに今回の処理を停止しました。","제공자의 응답 스트림에 오류가 발생했습니다. 불완전한 결과를 사용하지 않고 이번 처리를 중지했습니다.","El flujo de respuesta del proveedor devolvió un error. Se detuvo el turno sin usar resultados incompletos.","Le flux de réponse du fournisseur a signalé une erreur. Cet échange a été arrêté sans utiliser les résultats incomplets.","Der Antwortstrom des Anbieters meldete einen Fehler. Die Runde wurde ohne Nutzung unvollständiger Ergebnisse gestoppt.","Поток ответа провайдера вернул ошибку. Ход остановлен без использования неполных результатов."],
        ["Model"]=["模型 ID","模型 ID","Model ID","モデル ID","모델 ID","ID del modelo","ID du modèle","Modell-ID","ID модели"],
        ["native_project_trust_title"]=["信任此项目配置？","信任此專案設定？","Trust this project’s configuration?","このプロジェクトの設定を信頼しますか？","이 프로젝트 설정을 신뢰할까요?","¿Confiar en la configuración de este proyecto?","Faire confiance à la configuration de ce projet ?","Dieser Projektkonfiguration vertrauen?","Доверять настройкам этого проекта?"],
        ["native_project_trust_detail"]=["Codex 尚未信任此项目，因此项目配置、钩子和命令规则未加载。信任后，这些内容可影响助手行为并运行项目钩子；仅在你了解此项目内容时选择信任。此选择仅保存到 Fusion 的独立 Codex 配置，不会更改当前权限模式。","Codex 尚未信任此專案，因此未載入專案設定、掛鉤與命令規則。信任後，這些內容可影響助理行為並執行專案掛鉤；僅在了解專案內容時選擇信任。此選擇只儲存於 Fusion 獨立的 Codex 設定，不會變更目前權限模式。","Codex has not trusted this project, so its configuration, hooks and command rules are not loaded. Trusting them can affect assistant behavior and run project hooks. Trust only projects you understand. This choice is saved only in Fusion’s isolated Codex configuration and does not change the current permission mode.","Codex はこのプロジェクトをまだ信頼していないため、設定、フック、コマンド規則を読み込んでいません。信頼するとアシスタントの動作に影響し、プロジェクトのフックが実行される場合があります。内容を理解している場合のみ信頼してください。この選択は Fusion 専用の Codex 設定にのみ保存され、現在の権限モードは変更しません。","Codex가 아직 이 프로젝트를 신뢰하지 않아 설정, 훅, 명령 규칙을 불러오지 않았습니다. 신뢰하면 도우미 동작에 영향을 주고 프로젝트 훅을 실행할 수 있습니다. 내용을 이해하는 프로젝트만 신뢰하세요. 이 선택은 Fusion의 독립 Codex 설정에만 저장되며 현재 권한 모드를 바꾸지 않습니다.","Codex aún no confía en este proyecto, por lo que no carga su configuración, hooks ni reglas de comandos. Al confiar, pueden influir en el asistente y ejecutar hooks del proyecto. Confía solo si conoces su contenido. La elección se guarda únicamente en la configuración aislada de Codex de Fusion y no cambia los permisos actuales.","Codex ne fait pas encore confiance à ce projet ; sa configuration, ses hooks et ses règles de commandes ne sont donc pas chargés. Les autoriser peut modifier le comportement de l’assistant et exécuter des hooks. Faites confiance uniquement si vous connaissez le contenu. Ce choix est enregistré seulement dans la configuration Codex isolée de Fusion et ne change pas les autorisations actuelles.","Codex vertraut diesem Projekt noch nicht; Konfiguration, Hooks und Befehlsregeln werden daher nicht geladen. Vertrauen kann das Verhalten des Assistenten beeinflussen und Projekt-Hooks ausführen. Vertraue nur Projekten, deren Inhalt du kennst. Die Auswahl wird nur in Fusions separater Codex-Konfiguration gespeichert und ändert den aktuellen Berechtigungsmodus nicht.","Codex ещё не доверяет проекту, поэтому его настройки, хуки и правила команд не загружены. Доверие позволяет им влиять на помощника и запускать хуки проекта. Доверяйте только знакомым проектам. Выбор сохраняется только в отдельной конфигурации Codex для Fusion и не меняет текущий режим разрешений."],
        ["native_project_trust_allow"]=["信任此项目","信任此專案","Trust this project","このプロジェクトを信頼","이 프로젝트 신뢰","Confiar en este proyecto","Faire confiance à ce projet","Diesem Projekt vertrauen","Доверять этому проекту"],
        ["native_project_trust_skip"]=["不加载项目配置，继续","不載入專案設定，繼續","Continue without project configuration","プロジェクト設定を使わず続行","프로젝트 설정 없이 계속","Continuar sin la configuración del proyecto","Continuer sans la configuration du projet","Ohne Projektkonfiguration fortfahren","Продолжить без настроек проекта"],
        ["native_project_trust_failed"]=["项目配置仍被原生信任规则阻止，请检查 Codex 配置或管理员策略。","專案設定仍被原生信任規則阻擋，請檢查 Codex 設定或管理員原則。","Native trust rules still block the project configuration. Check Codex settings or administrator policies.","ネイティブの信頼規則により設定がブロックされています。Codex の設定や管理者ポリシーを確認してください。","기본 신뢰 규칙이 프로젝트 설정을 계속 차단하고 있습니다. Codex 설정이나 관리자 정책을 확인하세요.","Las reglas nativas de confianza siguen bloqueando la configuración. Revisa Codex o las políticas del administrador.","Les règles natives de confiance bloquent toujours la configuration. Vérifiez Codex ou les politiques administrateur.","Native Vertrauensregeln blockieren weiterhin die Projektkonfiguration. Prüfe Codex-Einstellungen oder Administratorrichtlinien.","Встроенные правила доверия по-прежнему блокируют настройки проекта. Проверьте Codex или политики администратора."],
    };
    internal static IEnumerable<string> Keys => Entries.Keys;
    internal static string Text(string key)=>AiToolsText.Text(key);
    internal static bool TryTranslateValue(string value,ApplicationLanguage language,out string text)
    {
        foreach(var pair in Entries)if(pair.Value.Contains(value,StringComparer.Ordinal))return TryText(pair.Key,language,out text);
        text="";return false;
    }
    internal static string EffortText(string effort)
    {
        return effort.Length==0&&TryText("ModelDefault",UiLanguage.Current,out var text)?text:effort;
    }
    internal static bool TryText(string key, ApplicationLanguage language, out string text)
    {
        key=key switch
        {
            "harness_permission_mode"=>"PermissionModeError","harness_windows_sandbox"=>"WindowsSandboxError","ai_cancelled"=>"Stopped",
            "harness_permission_mode_unsupported"=>"PermissionAutoUnsupported","harness_session_missing"=>"NativeSessionError",
            "harness_session_workspace" or "harness_workspace"=>"NativeWorkspaceError","harness_prompt_empty"=>"NativePromptEmpty",
            "harness_agent"=>"NativeAgentError","harness_prompt_uncertain"=>"NativeUncertain","harness_prompt_not_admitted"=>"NativeNotAdmitted",
            "harness_event_connection"=>"NativeEventError","harness_reconnecting"=>"NativeReconnecting",
            "harness_approval_unavailable"=>"NativeApprovalUnavailable","harness_question_unavailable"=>"NativeQuestionUnavailable",
            "execution_limit"=>"ExecutionLimit",
            "ai_connection_model"=>"ModelRequired",
            "ai_agent_options" or "harness_backend" or "harness_provider" or "harness_auth_mode" or "harness_endpoint"=>"AgentOptionsError",
            "harness_account_provider" or "ai_account_unsupported"=>"AccountScope",
            "harness_missing"=>"HarnessMissing","harness_start" or "harness_version"=>"HarnessStartError",
            "harness_error" or "harness_protocol" or "harness_tool_result"=>"HarnessResponseError",
            "ai_effort_unsupported" or "ai_protocol_effort_unsupported"=>"EffortUnavailable",_=>key
        };
        int i=language switch {ApplicationLanguage.SimplifiedChinese=>0,ApplicationLanguage.TraditionalChinese=>1,ApplicationLanguage.English=>2,ApplicationLanguage.Japanese=>3,ApplicationLanguage.Korean=>4,ApplicationLanguage.Spanish=>5,ApplicationLanguage.French=>6,ApplicationLanguage.German=>7,ApplicationLanguage.Russian=>8,_=>2};
        text=Entries.TryGetValue(key,out var values)?values[i]:"";return text.Length>0;
    }
}
